/// `Item.TurnToAir()` (Item.cs:49945)
pub unsafe fn turn_to_air(this: *mut terraria::item::Item) {
    if ((!((*this).type_ == 0)) || (!((*this).stack == 0)))
    {
        terraria::item::set_defaults(this, 0, Gc::<terraria::game_content::items::item_variant::ItemVariant>::NULL);
    }
}

/// `Item.OnPurchase(Item)` (Item.cs:49953)
pub unsafe fn on_purchase(this: *mut terraria::item::Item, mut item: Gc<terraria::item::Item>) {
    if (*item.ptr()).shop_custom_price.has_value
    {
        (*item.ptr()).shop_special_currency = (-1);
        (*item.ptr()).shop_custom_price = rt::zero::<Nullable<i32>>();
    }
}

/// `Item.GetStoreValue()` (Item.cs:49962)
pub unsafe fn get_store_value(this: *mut terraria::item::Item) -> i32 {
    if (*this).shop_custom_price.has_value
    {
        return (*this).shop_custom_price.value();
    }
    return (*this).value;
    rt::unreachable()
}

/// `Item.Serialize(BinaryWriter, bool)` (Item.cs:49971)
pub unsafe fn serialize(this: *mut terraria::item::Item, mut writer: Gc<rt::io::BinaryWriter>, mut writeFavorite: bool) {
    (*writer.ptr()).write::<i32>((*this).type_);
    (*writer.ptr()).write::<i32>((*this).stack);
    (*writer.ptr()).write::<u8>((*this).prefix);
    if writeFavorite
    {
        (*writer.ptr()).write::<bool>((*this).favorited);
    }
}

/// `Item.DeserializeFrom(BinaryReader, bool)` (Item.cs:49982)
pub unsafe fn deserialize_from(this: *mut terraria::item::Item, mut reader: Gc<rt::io::BinaryReader>, mut readFavorite: bool) {
    terraria::item::net_defaults(this, (*reader.ptr()).read_i32());
    (*this).stack = (*reader.ptr()).read_i32();
    let _ = terraria::item::prefix__int(this, ((*reader.ptr()).read_byte() as i32));
    if readFavorite
    {
        (*this).favorited = (*reader.ptr()).read_boolean();
    }
    if ((*this).type_ >= ((*terraria::id::item_id::s()).count as i32))
    {
        terraria::item::turn_to_air(this);
    }
}

/// `Item.ResetPrefix()` (Item.cs:49997)
pub unsafe fn reset_prefix(this: *mut terraria::item::Item) {
    if (!(((*this).prefix as i32) == 0))
    {
        (*this).prefix = 0u8;
        terraria::item::refresh(this, false);
    }
}

/// `Item.Refresh(bool)` (Item.cs:50006)
pub unsafe fn refresh(this: *mut terraria::item::Item, mut onlyIfVariantChanged: bool) {
    if ((!terraria::item::is_air(this)) && ((!onlyIfVariantChanged) || (!(terraria::game_content::items::item_variants::select_variant((*this).type_).addr() == terraria::item::variant(this).addr()))))
    {
        let mut flag: bool = (*this).favorited;
        let mut num: i32 = (*this).stack;
        let mut num2: i32 = (*this).type_;
        let mut prefixWeWant: i32 = ((*this).prefix as i32);
        terraria::item::set_defaults(this, num2, Gc::<terraria::game_content::items::item_variant::ItemVariant>::NULL);
        let _ = terraria::item::prefix__int(this, prefixWeWant);
        (*this).stack = num;
        (*this).favorited = flag;
    }
}

